import{_ as e,o as i,c as s,a2 as a}from"./chunks/framework.CBxkvBm_.js";const g=JSON.parse('{"title":"ReqIF Requirements Engineering & Formal Contract Entailment","description":"Native compiler support for OMG ReqIF (.reqif, .reqifz) requirements archives, Nelson-Oppen formal contract entailment prover, and SysML v2 / Modelica verification block projections in ModelScript.","frontmatter":{"title":"ReqIF Requirements Engineering & Formal Contract Entailment","description":"Native compiler support for OMG ReqIF (.reqif, .reqifz) requirements archives, Nelson-Oppen formal contract entailment prover, and SysML v2 / Modelica verification block projections in ModelScript."},"headers":[],"relativePath":"languages/reqif.md","filePath":"languages/reqif.md"}'),n={name:"languages/reqif.md"};function r(l,t,o,d,c,h){return i(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="reqif-requirements-engineering-formal-verification" tabindex="-1">ReqIF Requirements Engineering &amp; Formal Verification <a class="header-anchor" href="#reqif-requirements-engineering-formal-verification" aria-label="Permalink to &quot;ReqIF Requirements Engineering &amp; Formal Verification&quot;">​</a></h1><p>ModelScript delivers first-class support for <strong>ReqIF</strong> (Requirements Interchange Format, OMG ReqIF 1.0/1.2), the global standard for exchanging structured requirements across aerospace, automotive (ISO 26262), and medical device systems. ModelScript elevates requirements from dead documentation into <strong>computable digital contracts</strong> verifiable against physics simulations and architectural constraints.</p><hr><h2 id="capabilities-supported-formats" tabindex="-1">Capabilities &amp; Supported Formats <a class="header-anchor" href="#capabilities-supported-formats" aria-label="Permalink to &quot;Capabilities &amp; Supported Formats&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Format</th><th style="text-align:left;">Extension</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>OMG ReqIF XML Document</strong></td><td style="text-align:left;"><code>.reqif</code>, <code>.xml</code></td><td style="text-align:left;">XML document defining specification types, spec-objects, hierarchical spec-relations, data types, and attribute definitions.</td></tr><tr><td style="text-align:left;"><strong>ReqIF Compressed Archive</strong></td><td style="text-align:left;"><code>.reqifz</code>, <code>.zip</code></td><td style="text-align:left;">Zip archive packaging <code>.reqif</code> manifests alongside embedded media, diagrams, and attachments.</td></tr></tbody></table><h3 id="key-architectural-features" tabindex="-1">Key Architectural Features <a class="header-anchor" href="#key-architectural-features" aria-label="Permalink to &quot;Key Architectural Features&quot;">​</a></h3><ul><li><strong>Full OMG ReqIF 1.2 Ingestion &amp; Roundtrip:</strong><ul><li>Robust XML reader and serializer preserving internal identifiers (<code>IDENTIFIER</code>), specification hierarchies, multi-level parent-child relations, and custom attribute types (String, Integer, Real, Boolean, Date, Enumeration).</li></ul></li><li><strong>Formal Contract Extraction:</strong><ul><li>Automatically parses mathematical constraints from natural language requirement text (e.g. <code>latency &lt;= 50 ms</code>, <code>pressure &gt;= 15 bar</code>, <code>temp in [20, 80] C</code>).</li></ul></li><li><strong>Nelson-Oppen Mathematical Entailment Prover:</strong><ul><li>Uses the SMT/Nelson-Oppen theory coordinator in <code>@modelscript/runtime</code> to prove whether child sub-requirements strictly entail parent system-level requirements: $$\\bigwedge_{i} \\text{SubReq}_i \\models \\text{ParentReq}$$</li><li>Generates concrete numeric counterexamples when an entailment gap exists (e.g. child requirements permit a state that violates the parent requirement).</li></ul></li><li><strong>Automated Verification Projections:</strong><ul><li><strong>OMG SysML v2:</strong> Translates spec-objects into formal <code>requirement def</code> items with <code>doc</code> annotations, attribute definitions, and <code>satisfy</code> links.</li><li><strong>Modelica Verification Blocks:</strong> Generates acausal Modelica monitor blocks with assertions that trigger simulation failure when requirement bounds are breached.</li></ul></li><li><strong>Requirements Linters (<code>M7001</code>–<code>M7008</code>):</strong><ul><li>Detects dangling requirement relations, circular requirement hierarchies, unbounded safety contracts on ASIL requirements, and missing mandatory attributes.</li></ul></li></ul><hr><h2 id="command-line-interface-msx-reqif" tabindex="-1">Command Line Interface (<code>msx reqif</code>) <a class="header-anchor" href="#command-line-interface-msx-reqif" aria-label="Permalink to &quot;Command Line Interface (\`msx reqif\`)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reqif</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">actio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [files...] [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Description</th><th style="text-align:left;">Key Options</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>inspect</code></strong></td><td style="text-align:left;">Dumps requirement count, specification hierarchies, and attribute schemas.</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong><code>lint</code></strong></td><td style="text-align:left;">Runs structural consistency checks, link validation, and safety contract analysis.</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong><code>verify</code></strong></td><td style="text-align:left;">Runs Nelson-Oppen formal entailment proofs across requirement hierarchies.</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong><code>to-sysml</code></strong></td><td style="text-align:left;">Projects ReqIF specifications into OMG SysML v2 requirement definitions.</td><td style="text-align:left;"><code>--out=&lt;file.sysml&gt;</code></td></tr><tr><td style="text-align:left;"><strong><code>to-modelica</code></strong></td><td style="text-align:left;">Generates Modelica assertion blocks for in-simulation verification.</td><td style="text-align:left;"><code>--out=&lt;file.mo&gt;</code></td></tr></tbody></table><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Inspect requirement specifications and hierarchies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reqif</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SystemRequirements.reqif</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run pre-flight linting on ASIL safety requirements</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reqif</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BrakeSafetyRequirements.reqif</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Formally prove requirement hierarchy entailment with SMT counterexample generation</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reqif</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PowertrainContracts.reqif</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Project requirements to SysML v2 definitions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reqif</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to-sysml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AvionicsRequirements.reqif</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out=AvionicsRequirements.sysml</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Synthesize executable Modelica verification blocks</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reqif</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to-modelica</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ThermalLimits.reqif</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out=ThermalMonitors.mo</span></span></code></pre></div><hr><h2 id="requirements-linters-diagnostic-rules" tabindex="-1">Requirements Linters &amp; Diagnostic Rules <a class="header-anchor" href="#requirements-linters-diagnostic-rules" aria-label="Permalink to &quot;Requirements Linters &amp; Diagnostic Rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Code</th><th style="text-align:left;">Identifier</th><th style="text-align:left;">Severity</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>M7001</code></strong></td><td style="text-align:left;"><code>dangling-requirement-relation</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Spec-relation references a source or target spec-object absent from the document.</td></tr><tr><td style="text-align:left;"><strong><code>M7002</code></strong></td><td style="text-align:left;"><code>empty-specification</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Specification hierarchy declares no child spec-objects or requirements.</td></tr><tr><td style="text-align:left;"><strong><code>M7003</code></strong></td><td style="text-align:left;"><code>circular-requirement-hierarchy</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Child requirement hierarchy contains a circular loop back to a parent requirement.</td></tr><tr><td style="text-align:left;"><strong><code>M7004</code></strong></td><td style="text-align:left;"><code>untyped-spec-object</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Spec-object does not declare an associated <code>SPEC-OBJECT-TYPE</code>.</td></tr><tr><td style="text-align:left;"><strong><code>M7005</code></strong></td><td style="text-align:left;"><code>unbounded-safety-contract</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Requirement tagged with safety integrity level (e.g. ASIL-D / SIL-3) lacks formal mathematical bounds.</td></tr><tr><td style="text-align:left;"><strong><code>M7006</code></strong></td><td style="text-align:left;"><code>unparseable-contract-expression</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Requirement contract text cannot be parsed into formal propositional or linear arithmetic inequalities.</td></tr><tr><td style="text-align:left;"><strong><code>M7007</code></strong></td><td style="text-align:left;"><code>missing-mandatory-attribute</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Spec-object omits an attribute marked mandatory in its type definition.</td></tr><tr><td style="text-align:left;"><strong><code>M7008</code></strong></td><td style="text-align:left;"><code>entailment-gap-detected</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Formal proof proves that sub-requirements do not mathematically entail the parent requirement.</td></tr></tbody></table>`,16)])])}const m=e(n,[["render",r]]);export{g as __pageData,m as default};
